using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Animation;using System.Windows.Media.Effects;using System.Windows.Shapes;using System.Windows.Threading;
namespace SeraphimLuxury {
 partial class MainWindow {
  void LaunchChosen14(){var d=ControlCatalog14.All.FirstOrDefault(v=>v.Name==preferences.AutoLaunchApp);if(d==null)return;var a=preferences.Apps.FirstOrDefault(v=>ControlCatalog14.Definition(v)==d)??new AppEntry {Id="social-"+d.Id,Name=d.Name,Target="https://"+d.Domains[0]+"/",Social=true};RequestLaunch(a);}
  TextBlock greeting14;
  AppPolicy14 HostPolicy14(string host){var d=ControlCatalog14.Host(host??"");return d==null?null:ControlCatalog14.Policy(preferences,d.Id,d);}
  int HostUsage14(string host,DateTime day){var d=ControlCatalog14.Host(host??"");return d==null?TimeRules.Total(preferences,"web:"+host,day):ControlCatalog14.Usage(preferences,new AppEntry {Id="social-"+d.Id,Name=d.Name},day);}
  bool TrackHost14(AppEntry app,string host){if(app!=null)return true;var p=HostPolicy14(host);return p==null||p.TrackTime;}
  FrameworkElement AppTile14(AppEntry app,double size){var icon=ApplicationLogo(app,size*.64);var tile=new Border {Width=size,Height=size,CornerRadius=new CornerRadius(size*.23),Background=Visuals.Brush(app.Id=="roblox-studio"||app.Name.IndexOf("Roblox Studio",StringComparison.OrdinalIgnoreCase)>=0?"#187DCB":preferences.Premium?"#171A22":"#F1EEFA"),BorderThickness=new Thickness(.6),BorderBrush=Visuals.Brush("#45C1ADDD"),Child=icon};tile.Child=null;var inner=new Grid();var light=new Ellipse {Opacity=0,Fill=new RadialGradientBrush(Visuals.Color("#77B69CE3"),Colors.Transparent),Margin=new Thickness(2),IsHitTestVisible=false};inner.Children.Add(light);inner.Children.Add(icon);tile.Child=inner;tile.Loaded+=delegate{DependencyObject parent=tile;while(parent!=null&&!(parent is Button))parent=VisualTreeHelper.GetParent(parent);var button=parent as Button;if(button==null)return;button.MouseEnter+=delegate{light.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(1,TimeSpan.FromMilliseconds(preferences.ReducedMotion?1:260)));};button.MouseLeave+=delegate{light.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(0,TimeSpan.FromMilliseconds(preferences.ReducedMotion?1:380)));};};return tile;}
  void GlowButton14(Button b){var original=b.Background;var glow=new DropShadowEffect {Color=Visuals.Color("#B8A1F3"),BlurRadius=0,ShadowDepth=0,Opacity=0};b.Effect=glow;b.MouseEnter+=delegate{if(preferences.ReducedMotion){glow.Opacity=.3;glow.BlurRadius=12;return;}glow.BeginAnimation(DropShadowEffect.OpacityProperty,new DoubleAnimation(.2,TimeSpan.FromMilliseconds(230)));glow.BeginAnimation(DropShadowEffect.BlurRadiusProperty,new DoubleAnimation(14,TimeSpan.FromMilliseconds(320)));};b.MouseLeave+=delegate{glow.BeginAnimation(DropShadowEffect.OpacityProperty,new DoubleAnimation(0,TimeSpan.FromMilliseconds(preferences.ReducedMotion?1:340)));};}
  string FirstName14(){string name=AccountSession.Name;if(String.IsNullOrWhiteSpace(name)&&!testing)try{var account=AccountSession.Load(AccountSession.FilePath);name=account==null?null:account.Name;}catch{}return String.IsNullOrWhiteSpace(name)?"vous":name.Trim().Split(' ')[0];}
  void RefreshGreeting14(){if(greeting14!=null)PaintGreeting16(greeting14,FirstName14(),999);}
  void PaintGreeting16(TextBlock text,string name,int count){text.Inlines.Clear();string[] parts={"Hi, ",name,".\nWelcome to Seraphim."};int offset=0;for(int i=0;i<parts.Length;i++){int take=Math.Max(0,Math.Min(parts[i].Length,count-offset));if(take>0)text.Inlines.Add(new System.Windows.Documents.Run(parts[i].Substring(0,take)){Foreground=i==1?Visuals.Gold:Visuals.Text,FontSize=i==2?18:27});offset+=parts[i].Length;}}
  void Greeting14(){var row=new Grid {Margin=new Thickness(0,2,0,18),MinHeight=65};var text=Visuals.TextBlock("",27,Visuals.Text);greeting14=text;text.FontFamily=new FontFamily("Segoe UI");row.Children.Add(text);page.Children.Add(row);string name=FirstName14();int count=0,total=("Hi, "+name+".\nWelcome to Seraphim.").Length;bool erasing=false;DateTime wait=DateTime.UtcNow;var writer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(65)};writer.Tick+=delegate {if(DateTime.UtcNow<wait)return;if(!IsVisible||WindowState==WindowState.Minimized)return;if(erasing){count=Math.Max(0,count-2);if(count==0){erasing=false;wait=DateTime.UtcNow.AddMilliseconds(750);}}else {count++;if(count>=total){count=total;erasing=true;wait=DateTime.UtcNow.AddSeconds(4);}}PaintGreeting16(text,name,count);};row.Loaded+=delegate {if(testing||preferences.ReducedMotion)PaintGreeting16(text,name,999);else writer.Start();};row.Unloaded+=delegate {writer.Stop();};}
  Border Glass14(UIElement child,Thickness padding){return new Border {Child=child,Padding=padding,CornerRadius=new CornerRadius(17),BorderBrush=Visuals.Brush("#35B49BCD"),BorderThickness=new Thickness(.6),Background=Visuals.Brush(preferences.Premium?"#0DAF94D9":"#12FFFFFF")};}
